insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As manifestações processuais do representante do Ministério Público deverão ser fundamentadas.', '["Manifestações do MP devem ser fundamentadas."]'::jsonb, '["Dever de fundamentar."]'::jsonb, 'O Promotor justifica seu parecer.', '["Assertiva que dispensa fundamentação das manifestações do MP erra."]'::jsonb, '[]'::jsonb, '["Art. 75"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-78' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8a27da610c5776822510f93ab766c9dcbf2c7c5e86dec5271e5a93bdd24ec90a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regem-se pelas disposições da Lei as ações de responsabilidade por ofensa aos direitos da pessoa idosa, referentes à omissão ou ao oferecimento insatisfatório de acesso às ações e serviços de saúde; atendimento especializado à pessoa idosa com deficiência ou limitação incapacitante; atendimento especializado à pessoa idosa com doença infectocontagiosa; e serviço de assistência social visando ao amparo da pessoa idosa. As hipóteses não excluem a proteção judicial de outros interesses difusos, coletivos, individuais indisponíveis ou homogêneos.', '["Ações de responsabilidade por saúde, atendimento especializado e assistência social.","Rol não exclui outros interesses coletivos."]'::jsonb, '["Rol não taxativo (parágrafo único)."]'::jsonb, 'A ação coletiva busca o acesso a serviços de saúde da pessoa idosa.', '["Assertiva que considera taxativas as hipóteses do art. 79 erra."]'::jsonb, '[]'::jsonb, '["Art. 81"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-79' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '35128d201377b501ac3eb885034bbedb12cc820a2b96d8757a4ba82a268bf452'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As ações previstas neste Capítulo serão propostas no foro do domicílio da pessoa idosa, cujo juízo terá competência absoluta para processar a causa, ressalvadas as competências da Justiça Federal e a competência originária dos Tribunais Superiores.', '["Foro do domicílio da pessoa idosa.","Competência absoluta.","Ressalvada a Justiça Federal e os Tribunais Superiores."]'::jsonb, '["Competência ABSOLUTA do foro do domicílio da pessoa idosa."]'::jsonb, 'A ação coletiva é proposta no foro onde mora a pessoa idosa.', '["Assertiva que torna relativa a competência do domicílio da pessoa idosa erra: é absoluta."]'::jsonb, '[]'::jsonb, '["Art. 81"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-80' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '925dba83fb03b6b887268531a50689ee691828388c9b1d237da686665d902a84'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para as ações cíveis fundadas em interesses difusos, coletivos, individuais indisponíveis ou homogêneos, são legitimados concorrentemente o Ministério Público; a União, os Estados, o Distrito Federal e os Municípios; a Ordem dos Advogados do Brasil; e as associações legalmente constituídas há pelo menos 1 ano que incluam entre seus fins a defesa dos direitos da pessoa idosa, dispensada a autorização da assembleia, se houver prévia autorização estatutária. Admite-se litisconsórcio facultativo entre os Ministérios Públicos da União e dos Estados. Em caso de desistência ou abandono da ação por associação, o Ministério Público ou outro legitimado deverá assumir a titularidade ativa.', '["Legitimados: MP, entes federativos, OAB e associações com 1 ano de constituição.","Litisconsórcio facultativo entre MPs.","MP assume em caso de abandono pela associação."]'::jsonb, '["Associação: constituída há pelo menos 1 ano."]'::jsonb, 'A associação com dois anos de existência propõe ação em defesa de pessoas idosas.', '["Assertiva que exige 5 anos de constituição da associação erra: é 1 ano."]'::jsonb, '[]'::jsonb, '["Art. 80"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-81' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c2822ca08871c545acab021f09c0fced0df00091ce01f5f734a231fac7c6301d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para defesa dos interesses e direitos protegidos pela Lei, são admissíveis todas as espécies de ação pertinentes. Contra atos ilegais ou abusivos de autoridade pública ou agente de pessoa jurídica no exercício de atribuições de Poder Público, que lesem direito líquido e certo previsto na Lei, caberá ação mandamental, regida pela lei do mandado de segurança.', '["Todas as espécies de ação pertinentes.","Mandado de segurança contra ato ilegal de autoridade."]'::jsonb, '["Admite o MANDADO DE SEGURANÇA."]'::jsonb, 'A pessoa idosa impetra mandado de segurança contra ato abusivo de autoridade.', '["Assertiva que veda o mandado de segurança nas causas do Estatuto erra."]'::jsonb, '[]'::jsonb, '["Art. 83"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-82' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'cc7d10e792246c66f48443a1883b9446c594421647010deeaedd109223ba634e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na ação que tenha por objeto o cumprimento de obrigação de fazer ou não fazer, o juiz concederá a tutela específica da obrigação ou determinará providências que assegurem o resultado prático equivalente ao adimplemento. Sendo relevante o fundamento e havendo receio de ineficácia do provimento final, é lícito conceder a tutela liminarmente ou após justificação prévia. O juiz poderá impor multa diária ao réu, independentemente do pedido do autor, fixando prazo razoável. A multa só é exigível após o trânsito em julgado da sentença favorável, mas é devida desde o dia em que se configurou.', '["Tutela específica ou resultado prático equivalente.","Liminar com fundamento relevante e receio de ineficácia.","Multa diária, mesmo sem pedido.","Multa exigível após o trânsito em julgado, devida desde a configuração."]'::jsonb, '["Multa de OFÍCIO, exigível só após o trânsito em julgado."]'::jsonb, 'O juiz fixa multa diária contra o plano de saúde que se recusa a custear o tratamento.', '["Assertiva que exige pedido expresso do autor para a multa diária erra: o juiz pode impô-la de ofício."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-83' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3b10e18a110daeee8ca1872ee09dc15d3f383daff84a739030aa95f723fd2b0c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os valores das multas previstas na Lei reverterão ao Fundo da Pessoa Idosa, onde houver, ou, na falta, ao Fundo Municipal de Assistência Social, ficando vinculados ao atendimento à pessoa idosa. As multas não recolhidas até 30 dias após o trânsito em julgado serão exigidas por execução promovida pelo Ministério Público, nos mesmos autos, facultada igual iniciativa aos demais legitimados em caso de inércia.', '["Multas revertem ao Fundo da Pessoa Idosa ou ao Fundo Municipal de Assistência Social.","Execução pelo MP após 30 dias do trânsito em julgado."]'::jsonb, '["Prazo de 30 dias para o recolhimento."]'::jsonb, 'A multa aplicada financia programas para pessoas idosas.', '["Assertiva que destina as multas ao Tesouro geral erra: vão ao fundo vinculado."]'::jsonb, '[]'::jsonb, '["Art. 83"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-84' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'cab72fbc86df03b2f2ee1c9a675dad3be8daf98840acde38c136707c09858368'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz poderá conferir efeito suspensivo aos recursos, para evitar dano irreparável à parte.', '["Efeito suspensivo para evitar dano irreparável."]'::jsonb, '["Efeito suspensivo é excepcional."]'::jsonb, 'O juiz suspende os efeitos da decisão para evitar dano irreparável.', '["Assertiva que torna automático o efeito suspensivo dos recursos erra."]'::jsonb, '[]'::jsonb, '["Art. 86"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-85' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e7bc3c79e30d94e524d08968420d0b15644dccf40f9dfdf3905c25ef0d590683'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
