insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitada em julgado a sentença que impuser condenação ao Poder Público, o juiz determinará a remessa de peças à autoridade competente, para apuração da responsabilidade civil e administrativa do agente a que se atribua a ação ou omissão.', '["Remessa de peças para apurar a responsabilidade do agente público."]'::jsonb, '["Responsabilidade civil e administrativa do agente."]'::jsonb, 'Após condenar o Município, o juiz manda apurar a responsabilidade do servidor.', '["Assertiva que isenta o agente público de apuração após condenação do Poder Público erra."]'::jsonb, '[]'::jsonb, '["Art. 87"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-86' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '12dc1294c2c6a196ea0e41b467428241f1b9e89296daa21c0e6ae90985232133'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Decorridos 60 dias do trânsito em julgado da sentença condenatória favorável à pessoa idosa sem que o autor lhe promova a execução, deverá fazê-lo o Ministério Público, facultada igual iniciativa aos demais legitimados, como assistentes ou assumindo o polo ativo, em caso de inércia desse órgão.', '["Execução pelo MP após 60 dias de inércia do autor.","Demais legitimados podem assumir."]'::jsonb, '["Prazo de 60 dias."]'::jsonb, 'Se o autor não executa a sentença em 60 dias, o Promotor o faz.', '["Assertiva que fixa em 30 dias o prazo para o MP executar erra: são 60."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
