insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas ações de que trata este Capítulo, não haverá adiantamento de custas, emolumentos, honorários periciais e quaisquer outras despesas. Não se imporá sucumbência ao Ministério Público.', '["Sem adiantamento de custas e despesas.","MP não sofre sucumbência."]'::jsonb, '["Sem sucumbência ao Ministério Público."]'::jsonb, 'A ação coletiva dispensa o pagamento antecipado de custas.', '["Assertiva que condena o MP em honorários de sucumbência erra."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-88' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '9a255335f4e1b2599b9dc5530d0bc1b641b927712f8405785456c27db32d831f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
