insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Qualquer pessoa poderá, e o servidor deverá, provocar a iniciativa do Ministério Público, prestando-lhe informações sobre os fatos que constituam objeto de ação civil e indicando-lhe os elementos de convicção.', '["Qualquer pessoa pode provocar o MP.","O servidor tem o dever de fazê-lo."]'::jsonb, '["Para o servidor é DEVER; para o cidadão é faculdade."]'::jsonb, 'O servidor que sabe de uma irregularidade informa o Ministério Público.', '["Assertiva que torna facultativa a comunicação ao MP para o servidor erra: ele deve provocar."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-89' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '74cfbc83257c00057fe7a4e55dd7764ffd10f94ea7378ab46d1659202a2329c8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os agentes públicos em geral, os juízes e tribunais, no exercício de suas funções, quando tiverem conhecimento de fatos que possam configurar crime de ação pública contra a pessoa idosa ou ensejar a propositura de ação para sua defesa, devem encaminhar as peças pertinentes ao Ministério Público.', '["Dever de remeter peças ao MP."]'::jsonb, '["Dever de agentes públicos, juízes e tribunais."]'::jsonb, 'O juiz que percebe indício de crime contra pessoa idosa envia as peças ao MP.', '["Assertiva que dispensa os juízes de comunicar o MP erra."]'::jsonb, '[]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-90' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3cbbf105348e4b354bd6c06bd2d5484ee0cd2649e9ad457cfc952bc8f0705a0c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para instruir a petição inicial, o interessado poderá requerer às autoridades competentes as certidões e informações que julgar necessárias, que serão fornecidas no prazo de 10 dias.', '["Certidões e informações em 10 dias."]'::jsonb, '["Prazo de 10 dias."]'::jsonb, 'O autor pede certidões a órgãos públicos para instruir a ação.', '["Assertiva que fixa em 30 dias o prazo para fornecer certidões erra: são 10."]'::jsonb, '[]'::jsonb, '["Art. 92"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-91' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '88d8783c45359267514c20a3760eafab5c54b1fe5a65eef5b6e502e7b17f0760'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Ministério Público poderá instaurar, sob sua presidência, inquérito civil, ou requisitar de qualquer pessoa, organismo público ou particular, certidões, informações, exames ou perícias, no prazo que assinalar, não inferior a 10 dias. Esgotadas as diligências, se se convencer da inexistência de fundamento, determinará o arquivamento, fundamentadamente. Os autos arquivados serão remetidos, sob pena de falta grave, em 3 dias ao Conselho Superior do Ministério Público ou à Câmara de Coordenação e Revisão. Até a homologação ou rejeição, as associações legitimadas poderão apresentar razões escritas ou documentos. Se não for homologado o arquivamento, será designado outro membro para ajuizar a ação.', '["Inquérito civil presidido pelo MP.","Requisição com prazo não inferior a 10 dias.","Arquivamento fundamentado, remetido em 3 dias ao Conselho Superior.","Rejeição do arquivamento: outro membro ajuíza a ação."]'::jsonb, '["Remessa do arquivamento em 3 dias, sob pena de falta grave."]'::jsonb, 'O Promotor arquiva o inquérito civil e remete os autos ao Conselho Superior em três dias.', '["Assertiva que dispensa a remessa do arquivamento ao Conselho Superior erra."]'::jsonb, '[]'::jsonb, '["Art. 74"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-92' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '04092ae95450c4fd126d9583f4b0175bbfcb2d005282af097867454884f70399'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicam-se subsidiariamente, no que couber, as disposições da Lei da Ação Civil Pública (Lei nº 7.347, de 24 de julho de 1985).', '["Aplicação subsidiária da Lei da Ação Civil Pública."]'::jsonb, '["Subsidiariedade."]'::jsonb, 'Na falta de regra, aplica-se a Lei da Ação Civil Pública.', '["Assertiva que afasta a Lei da Ação Civil Pública erra: ela é subsidiária."]'::jsonb, '[]'::jsonb, '["Art. 81"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-93' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2402918247d5d543054977d3ef867089cd08227033ea96102962396c1e3b03ca'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aos crimes previstos na Lei aplicam-se, no que couber, o Código Penal e o Código de Processo Penal. Aos crimes previstos na Lei e aos crimes praticados com violência contra a pessoa idosa, independentemente da pena prevista, não se aplica a Lei dos Juizados Especiais (Lei nº 9.099, de 26 de setembro de 1995).', '["Código Penal e Código de Processo Penal subsidiários.","Afasta a Lei dos Juizados Especiais nos crimes do Estatuto e nos crimes com violência contra pessoa idosa."]'::jsonb, '["ATUALIZAÇÃO: redação do parágrafo único dada pela Lei nº 14.423, de 2022 (afasta os Juizados também nos crimes com violência contra a pessoa idosa).","Sem transação penal e sem suspensão do processo da Lei nº 9.099."]'::jsonb, 'O crime de abandono de pessoa idosa não segue o rito dos Juizados Especiais.', '["Assertiva que aplica a transação penal aos crimes do Estatuto erra: a Lei nº 9.099 não se aplica."]'::jsonb, '[]'::jsonb, '["Lei dos Juizados Especiais"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-94' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '09bc79b97a026a3c1c5aab72a2fc53982b424c57dfe4738d38008d1e286144ec'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os crimes definidos na Lei são de ação penal pública incondicionada, não se lhes aplicando os arts. 181 e 182 do Código Penal.', '["Ação penal pública incondicionada.","Afastadas as imunidades penais dos arts. 181 e 182 do Código Penal."]'::jsonb, '["Sem imunidade penal entre parentes (arts. 181 e 182 do Código Penal)."]'::jsonb, 'O filho que se apropria da aposentadoria do pai idoso responde pelo crime, apesar do parentesco.', '["Assertiva que aplica a imunidade familiar aos crimes do Estatuto erra: os arts. 181 e 182 não se aplicam."]'::jsonb, '[]'::jsonb, '["Art. 102"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-95' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '364d06826aa8c6f5f95b617b1403170e77df1a958c352a27643be6a7017b2fc9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Discriminar pessoa idosa, impedindo ou dificultando seu acesso a operações bancárias, aos meios de transporte, ao direito de contratar ou por qualquer outro meio necessário ao exercício da cidadania, por motivo de idade: reclusão de 6 meses a 1 ano e multa. Na mesma pena quem desdenhar, humilhar, menosprezar ou discriminar pessoa idosa, por qualquer motivo. A pena aumenta de 1/3 se a vítima estiver sob os cuidados ou responsabilidade do agente. Não constitui crime a negativa de crédito motivada por superendividamento da pessoa idosa.', '["Discriminação por motivo de idade: reclusão de 6 meses a 1 ano e multa.","Humilhar ou menosprezar a pessoa idosa, por qualquer motivo.","Aumento de 1/3 se a vítima estiver sob os cuidados do agente.","Negativa de crédito por superendividamento não é crime."]'::jsonb, '["ATUALIZAÇÃO: o §3º (negativa de crédito por superendividamento) foi incluído por lei posterior.","O §1º pune humilhar ou menosprezar POR QUALQUER MOTIVO."]'::jsonb, 'O banco que impede a pessoa idosa de contratar, só pela idade, comete o crime.', '["Assertiva que considera crime toda negativa de crédito à pessoa idosa erra: a negativa por superendividamento não é crime."]'::jsonb, '[]'::jsonb, '["Art. 95"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-96' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '34c9fcce0657acd3e4606cbe3f60496147071e6bb1bf0172032a89057a3f1d8f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar de prestar assistência à pessoa idosa, quando possível fazê-lo sem risco pessoal, em situação de iminente perigo, ou recusar, retardar ou dificultar sua assistência à saúde, sem justa causa, ou não pedir, nesses casos, o socorro de autoridade pública: detenção de 6 meses a 1 ano e multa. A pena é aumentada de metade se da omissão resulta lesão corporal de natureza grave, e triplicada se resulta a morte.', '["Omissão de socorro à pessoa idosa.","Detenção de 6 meses a 1 ano e multa.","Aumento de metade (lesão grave) e triplicada (morte)."]'::jsonb, '["Pena triplicada se resulta MORTE."]'::jsonb, 'Quem vê a pessoa idosa em perigo e não pede socorro comete o crime.', '["Assertiva que prevê reclusão para o crime do art. 97 erra: é detenção."]'::jsonb, '[]'::jsonb, '["Art. 98"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-97' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5e155725aa8f3061085332191e4db647718c41d163aa64602a2ed302dff2b668'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Abandonar a pessoa idosa em hospitais, casas de saúde, entidades de longa permanência ou congêneres, ou não prover suas necessidades básicas, quando obrigado por lei ou mandado: detenção de 6 meses a 3 anos e multa.', '["Abandono em hospitais, casas de saúde ou entidades.","Não prover necessidades básicas, quando obrigado.","Detenção de 6 meses a 3 anos e multa."]'::jsonb, '["Detenção de 6 meses a 3 anos."]'::jsonb, 'A família que abandona a pessoa idosa no hospital pratica o crime.', '["Assertiva que limita o crime ao abandono em hospitais erra: inclui não prover as necessidades básicas."]'::jsonb, '[]'::jsonb, '["Art. 99"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-98' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7b327ac328a26fede91a839b623f2436303867c5571de0d3b8ff1e548e4155a2'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Expor a perigo a integridade e a saúde, física ou psíquica, da pessoa idosa, submetendo-a a condições desumanas ou degradantes ou privando-a de alimentos e cuidados indispensáveis, quando obrigado a fazê-lo, ou sujeitando-a a trabalho excessivo ou inadequado: reclusão de 2 a 5 anos. Se resulta lesão corporal grave, reclusão de 3 a 7 anos. Se resulta morte, reclusão de 8 a 14 anos.', '["Exposição a perigo, condições desumanas ou privação de cuidados.","Reclusão de 2 a 5 anos.","Lesão grave: 3 a 7 anos.","Morte: 8 a 14 anos."]'::jsonb, '["Pena de RECLUSÃO de 2 a 5 anos."]'::jsonb, 'Deixar a pessoa idosa sem comida e cuidados configura o crime.', '["Assertiva que prevê detenção para o crime do art. 99 erra: é reclusão."]'::jsonb, '[]'::jsonb, '["Art. 98"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-99' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '406a475d430533472312b1262d1caec2e4dad7d2917efd1f235f4994b1d4c4f0'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constitui crime punível com reclusão de 6 meses a 1 ano e multa: obstar o acesso de alguém a qualquer cargo público por motivo de idade; negar a alguém, por motivo de idade, emprego ou trabalho; recusar, retardar ou dificultar atendimento ou deixar de prestar assistência à saúde, sem justa causa, a pessoa idosa; deixar de cumprir, retardar ou frustrar, sem justo motivo, a execução de ordem judicial expedida na ação civil a que alude a Lei; e recusar, retardar ou omitir dados técnicos indispensáveis à propositura da ação civil, quando requisitados pelo Ministério Público.', '["Obstar acesso a cargo público por idade.","Negar emprego ou trabalho por idade.","Recusar atendimento de saúde.","Descumprir ordem judicial na ação civil.","Omitir dados técnicos requisitados pelo MP."]'::jsonb, '["Reclusão de 6 meses a 1 ano e multa."]'::jsonb, 'A empresa que nega emprego por causa da idade comete o crime.', '["Assertiva que prevê detenção para esses crimes erra: é reclusão."]'::jsonb, '[]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-100' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7568eb98fefbbf0cf607724b10d30c20a58623a2951befd4ec61e30e8173a57c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar de cumprir, retardar ou frustrar, sem justo motivo, a execução de ordem judicial expedida nas ações em que for parte ou interveniente a pessoa idosa: detenção de 6 meses a 1 ano e multa.', '["Descumprir ordem judicial nas ações de pessoa idosa.","Detenção de 6 meses a 1 ano e multa."]'::jsonb, '["Detenção de 6 meses a 1 ano."]'::jsonb, 'Quem retarda o cumprimento de ordem judicial em favor da pessoa idosa pratica o crime.', '["Assertiva que prevê reclusão para esse crime erra: é detenção."]'::jsonb, '[]'::jsonb, '["Art. 100"]'::jsonb, 'under_review', 'claude'
