insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apropriar-se de ou desviar bens, proventos, pensão ou qualquer outro rendimento da pessoa idosa, dando-lhes aplicação diversa da de sua finalidade: reclusão de 1 a 4 anos e multa.', '["Apropriação ou desvio de bens e rendimentos da pessoa idosa.","Reclusão de 1 a 4 anos e multa."]'::jsonb, '["Sem imunidade familiar (art. 95)."]'::jsonb, 'O filho que usa a aposentadoria do pai idoso em benefício próprio comete o crime.', '["Assertiva que aplica a imunidade penal entre parentes a esse crime erra."]'::jsonb, '[]'::jsonb, '["Art. 95"]'::jsonb, 'under_review', 'claude'
