insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Negar o acolhimento ou a permanência da pessoa idosa, como abrigada, por recusa desta em outorgar procuração à entidade de atendimento: detenção de 6 meses a 1 ano e multa.', '["Negar acolhimento por recusa de procuração à entidade."]'::jsonb, '["A entidade não pode exigir procuração."]'::jsonb, 'A casa de repouso que recusa a pessoa idosa porque ela não deu procuração comete o crime.', '["Assertiva que permite à entidade exigir procuração para abrigar erra."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-103' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f0e6f1cbda8b5b171ca44bda188a21c2afab2cb83478cfdc8ddf004a17d25a5c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
