insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Reter o cartão magnético de conta bancária relativa a benefícios, proventos ou pensão da pessoa idosa, bem como qualquer outro documento com objetivo de assegurar recebimento ou ressarcimento de dívida: detenção de 6 meses a 2 anos e multa.', '["Reter cartão bancário ou documento para garantir dívida.","Detenção de 6 meses a 2 anos e multa."]'::jsonb, '["Muito comum em empréstimos consignados."]'::jsonb, 'O agiota que retém o cartão da aposentadoria da pessoa idosa comete o crime.', '["Assertiva que permite reter o cartão como garantia de dívida erra."]'::jsonb, '[]'::jsonb, '["Art. 102"]'::jsonb, 'under_review', 'claude'
