select u.id, u.content_sha256, 'Exibir ou veicular, por qualquer meio de comunicação, informações ou imagens depreciativas ou injuriosas à pessoa idosa: detenção de 1 a 3 anos e multa.', '["Exibir ou veicular imagens ou informações depreciativas.","Detenção de 1 a 3 anos e multa."]'::jsonb, '["Alcança qualquer meio de comunicação."]'::jsonb, 'Publicar vídeo humilhante de uma pessoa idosa na internet é crime.', '["Assertiva que restringe o crime à imprensa tradicional erra: abrange qualquer meio."]'::jsonb, '[]'::jsonb, '["Art. 96"]'::jsonb, 'under_review', 'claude'
