insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Induzir pessoa idosa sem discernimento de seus atos a outorgar procuração para fins de administração de bens ou deles dispor livremente: reclusão de 2 a 4 anos.', '["Induzir pessoa sem discernimento a outorgar procuração.","Reclusão de 2 a 4 anos."]'::jsonb, '["Vítima sem discernimento."]'::jsonb, 'Convencer uma pessoa idosa com demência a assinar procuração geral é crime.', '["Assertiva que prevê detenção para esse crime erra: é reclusão."]'::jsonb, '[]'::jsonb, '["Art. 107"]'::jsonb, 'under_review', 'claude'
