insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Orçamento da Seguridade Social destinará ao Fundo Nacional de Assistência Social, até que o Fundo Nacional da Pessoa Idosa seja criado, os recursos necessários, em cada exercício financeiro, para aplicação em programas e ações relativos à pessoa idosa.', '["Recursos da Seguridade Social ao Fundo Nacional de Assistência Social, até a criação do Fundo da Pessoa Idosa."]'::jsonb, '["Dispositivo transitório."]'::jsonb, 'Enquanto não há fundo próprio, os recursos vão ao Fundo Nacional de Assistência Social.', '["Assertiva que cria o Fundo Nacional da Pessoa Idosa nesse artigo erra: ele é futuro."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
