insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O visto é o documento que dá a seu titular expectativa de ingresso em território nacional.', '["Visto dá EXPECTATIVA de ingresso."]'::jsonb, '["Visto não garante a entrada: é expectativa."]'::jsonb, 'Mesmo com visto, a entrada pode ser impedida em casos legais.', '["Assertiva que considera o visto direito líquido e certo de ingresso erra: ele dá expectativa."]'::jsonb, '[]'::jsonb, '["Art. 45"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-6' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '48eb1a3c0f7136be5bea135005c8e9d66640915ecb569add85df060fba2d8743'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
