insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O visto será concedido por embaixadas, consulados-gerais, consulados, vice-consulados e, quando habilitados pelo Executivo, por escritórios comerciais e de representação do Brasil no exterior. Excepcionalmente, os vistos diplomático, oficial e de cortesia poderão ser concedidos no Brasil.', '["Concessão por representações no exterior.","Exceção: vistos diplomático, oficial e de cortesia podem ser concedidos no Brasil."]'::jsonb, '["Vistos especiais podem ser concedidos no Brasil, excepcionalmente."]'::jsonb, 'O consulado brasileiro no exterior emite o visto de turismo.', '["Assertiva que permite à Polícia Federal emitir visto de visita no Brasil como regra erra."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-7' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a3a23f7fa19ae65e622e808025f354b5db915a9202dc373cc52c214e71c43b3f'
