insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não se concederá visto a quem não preencher os requisitos para o tipo de visto pleiteado; a quem comprovadamente ocultar condição impeditiva de concessão de visto ou de ingresso no País; e a menor de 18 anos desacompanhado ou sem autorização de viagem por escrito dos responsáveis legais ou de autoridade competente.', '["Falta dos requisitos.","Ocultação de condição impeditiva.","Menor de 18 anos sem acompanhante ou autorização."]'::jsonb, '["Hipóteses de NÃO concessão (obrigatória)."]'::jsonb, 'O consulado não concede visto a menor viajando sozinho sem autorização.', '["Assertiva que permite o visto a menor desacompanhado sem autorização erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-10' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e9cef6c6c6de77667e1b26bd7a9b3302f6d8dc448024931f90482d8c9c545688'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Poderá ser denegado visto a quem se enquadrar em pelo menos um dos casos de impedimento dos incisos I, II, III, IV e IX do art. 45. A pessoa que tiver visto brasileiro denegado será impedida de ingressar no País enquanto permanecerem as condições que ensejaram a denegação.', '["Denegação por impedimentos do art. 45 (I, II, III, IV e IX).","Impedimento de ingresso enquanto persistirem as condições."]'::jsonb, '["Denegar é FACULDADE; não conceder (art. 10) é dever."]'::jsonb, 'A pessoa condenada por terrorismo pode ter o visto denegado.', '["Assertiva que torna obrigatória a denegação nas hipóteses do art. 45 erra: ''poderá''."]'::jsonb, '[]'::jsonb, '["Art. 45"]'::jsonb, 'under_review', 'claude'
