and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao solicitante que pretenda ingressar ou permanecer em território nacional poderá ser concedido visto de visita, temporário, diplomático, oficial ou de cortesia.', '["Cinco tipos de visto: visita, temporário, diplomático, oficial e de cortesia."]'::jsonb, '["Antes havia mais categorias; hoje são cinco."]'::jsonb, 'O trabalhador estrangeiro recebe visto temporário.', '["Assertiva que inclui o visto permanente entre os tipos erra: não há."]'::jsonb, '[]'::jsonb, '["Arts. 13 e 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-12' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2cf9e79b3db9e1d247ce210fa4b1b9aacd17da653cc61e5ce89f13cbcb818f11'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O visto de visita poderá ser concedido ao visitante que venha ao Brasil para estada de curta duração, sem intenção de estabelecer residência, para turismo, negócios, trânsito, atividades artísticas ou desportivas e outras hipóteses do regulamento. É vedado ao beneficiário exercer atividade remunerada no Brasil, mas ele pode receber diária, ajuda de custo, cachê, pró-labore ou outras despesas de viagem e concorrer a prêmios. O visto de visita não será exigido em escala ou conexão, desde que o visitante não deixe a área de trânsito internacional.', '["Turismo, negócios, trânsito, atividades artísticas ou desportivas.","Vedada atividade remunerada.","Pode receber diária, ajuda de custo, cachê e prêmios.","Sem visto em escala na área de trânsito."]'::jsonb, '["Visitante NÃO pode exercer atividade remunerada."]'::jsonb, 'O turista não pode trabalhar no Brasil com visto de visita.', '["Assertiva que permite ao visitante exercer atividade remunerada erra: é vedada."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-13' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '690c0808e5ad2ff68e1e172a8af6f06e415a71b37d3c12416da6d63709401206'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O visto temporário poderá ser concedido ao imigrante que venha ao Brasil para estabelecer residência por tempo determinado, com finalidade de pesquisa, ensino ou extensão acadêmica; tratamento de saúde; acolhida humanitária; estudo; trabalho; férias-trabalho; atividade religiosa ou serviço voluntário; investimento ou atividade de relevância; reunião familiar; atividades artísticas ou desportivas com contrato; ou quando for beneficiário de tratado ou nas hipóteses do regulamento. Para pesquisa, o visto pode ser concedido com ou sem vínculo com a instituição. Para tratamento de saúde, o imigrante e seu acompanhante devem comprovar meios de subsistência.', '["Residência por tempo determinado.","Finalidades: pesquisa, saúde, acolhida humanitária, estudo, trabalho, férias-trabalho, voluntariado, investimento, reunião familiar e outras.","Beneficiário de tratado."]'::jsonb, '["Visto TEMPORÁRIO: residência por tempo determinado."]'::jsonb, 'O estudante estrangeiro recebe visto temporário para estudo.', '["Assertiva que concede visto temporário apenas para trabalho erra: há várias finalidades."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-14' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '90c29b36fb0c8f84287b402f8eedaf113ca7fe5ec1242b36ff10abb1c96fa26e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os vistos diplomático, oficial e de cortesia serão concedidos, prorrogados ou dispensados na forma da Lei e de regulamento. Os vistos diplomático e oficial poderão ser transformados em autorização de residência, o que importará cessação de todas as prerrogativas, privilégios e imunidades decorrentes do visto.', '["Concessão e dispensa na forma da lei e do regulamento.","Transformação em autorização de residência faz cessar as imunidades."]'::jsonb, '["Transformação em residência faz CESSAR imunidades."]'::jsonb, 'O diplomata que passa a residir como imigrante perde as imunidades.', '["Assertiva que mantém as imunidades após a transformação em residência erra."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-15' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b97de73bafd15f8da75388abd4da7794eb11d3595ce8ee97e104e4be23d5fb21'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
