insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os vistos diplomático e oficial poderão ser concedidos a autoridades e funcionários estrangeiros que viajem ao Brasil em missão oficial, transitória ou permanente, representando Estado estrangeiro ou organismo internacional reconhecido. Não se aplica a legislação trabalhista brasileira ao titular desses vistos, e eles poderão ser estendidos aos dependentes.', '["Missão oficial de Estado ou organismo internacional.","Sem aplicação da legislação trabalhista brasileira ao titular.","Extensão aos dependentes."]'::jsonb, '["A CLT não se aplica ao titular desses vistos."]'::jsonb, 'O embaixador estrangeiro e seus dependentes recebem visto diplomático.', '["Assertiva que submete o titular do visto diplomático à legislação trabalhista brasileira erra."]'::jsonb, '[]'::jsonb, '["Art. 17"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-16' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'bfc121c7a6e2b53f99ad5c895f2f2af1fa52da6d22b063ee6e675f6e1ede37e9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
