insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O titular de visto diplomático ou oficial somente poderá ser remunerado por Estado estrangeiro ou organismo internacional, ressalvado tratado com cláusula específica. O dependente poderá exercer atividade remunerada no Brasil, sob a legislação trabalhista brasileira, desde que seja nacional de país que assegure reciprocidade ao brasileiro, por comunicação diplomática.', '["Titular remunerado só por Estado estrangeiro ou organismo internacional.","Dependente pode trabalhar, com reciprocidade."]'::jsonb, '["Dependente pode trabalhar mediante RECIPROCIDADE."]'::jsonb, 'O cônjuge de um diplomata pode trabalhar no Brasil se houver reciprocidade.', '["Assertiva que proíbe o dependente do diplomata de trabalhar em qualquer caso erra."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
