insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O empregado particular titular de visto de cortesia somente poderá exercer atividade remunerada para o titular de visto diplomático, oficial ou de cortesia ao qual esteja vinculado, sob a legislação trabalhista brasileira. O titular do visto diplomático, oficial ou de cortesia é responsável pela saída de seu empregado do território nacional.', '["Empregado particular com visto de cortesia trabalha só para o seu empregador.","Legislação trabalhista brasileira.","Empregador responsável pela saída do empregado."]'::jsonb, '["O empregador responde pela saída do empregado."]'::jsonb, 'A empregada doméstica de um diplomata trabalha apenas para ele.', '["Assertiva que permite ao empregado de cortesia trabalhar para qualquer pessoa erra."]'::jsonb, '[]'::jsonb, '["Art. 17"]'::jsonb, 'under_review', 'claude'
