insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O asilo político, que constitui ato discricionário do Estado, poderá ser diplomático ou territorial e será outorgado como instrumento de proteção à pessoa. Regulamento disporá sobre as condições para a concessão e a manutenção de asilo.', '["Asilo político é ato discricionário.","Pode ser diplomático ou territorial."]'::jsonb, '["Asilo é DISCRICIONÁRIO; refúgio tem critérios próprios."]'::jsonb, 'O Estado decide se concede o asilo territorial a um perseguido político.', '["Assertiva que considera o asilo ato vinculado erra: é discricionário."]'::jsonb, '[{"termo":"Asilo diplomático","significado":"Concedido em embaixada ou consulado."}]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-27' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '93210017c19a47566e88c34f9ce2df36fdd7fa2ae71b4150ad29f645fae43465'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
