insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não se concederá asilo a quem tenha cometido crime de genocídio, crime contra a humanidade, crime de guerra ou crime de agressão, nos termos do Estatuto de Roma do Tribunal Penal Internacional, de 1998, promulgado pelo Decreto nº 4.388, de 25 de setembro de 2002.', '["Vedado o asilo a autores de genocídio, crimes contra a humanidade, de guerra e de agressão."]'::jsonb, '["Quatro crimes do Estatuto de Roma."]'::jsonb, 'Quem cometeu genocídio não pode receber asilo.', '["Assertiva que permite asilo a autor de crime de guerra erra."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
