insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regulamento disporá sobre a perda e o cancelamento da autorização de residência em razão de fraude ou de ocultação de condição impeditiva de concessão de visto, de ingresso ou de permanência no País, observado procedimento administrativo que garanta o contraditório e a ampla defesa.', '["Perda por fraude ou ocultação de condição impeditiva.","Contraditório e ampla defesa."]'::jsonb, '["Exige procedimento com contraditório."]'::jsonb, 'A autorização obtida com documento falso pode ser cancelada, após defesa.', '["Assertiva que permite o cancelamento sem contraditório erra."]'::jsonb, '[]'::jsonb, '["Art. 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-33' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8022d18fdd69b1a82872c477f4076e1d6c4f43b7ccd571d7302f7c04c8f2780f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
