insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O visto ou a autorização de residência para reunião familiar será concedido ao cônjuge ou companheiro, sem discriminação; ao filho de imigrante beneficiário de autorização de residência, ou que tenha filho brasileiro ou imigrante beneficiário; ao ascendente, descendente até o segundo grau ou irmão de brasileiro ou de imigrante beneficiário; e a quem tenha brasileiro sob sua tutela ou guarda.', '["Cônjuge ou companheiro, sem discriminação.","Filho de imigrante ou pai de filho brasileiro.","Ascendente, descendente até o segundo grau ou irmão.","Tutela ou guarda de brasileiro."]'::jsonb, '["Cônjuge e companheiro SEM discriminação (inclui união homoafetiva)."]'::jsonb, 'O estrangeiro com filho brasileiro obtém residência por reunião familiar.', '["Assertiva que exclui o companheiro do rol da reunião familiar erra."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-37' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '197600e813229d6929aae4c3f741ed568c485948093290f88f1a945c1dd1a4d4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
